dags_router = AirflowRouter(tags=["DAG"], prefix="/dags")

# Sort keys accepted by the DAG list for the latest DagRun, mapped to the
# internal keys that generate_dag_with_latest_run_query() recognizes to join
# the latest run. ``state``/``start_date`` have no DagModel column, so they
# must resolve to DagRun columns (see SortParam below) and trigger the join.
_DAG_SORT_ALIASES = {
    "state": "last_run_state",
    "start_date": "last_run_start_date",
}


def _normalize_dag_order_by(order_by: SortParam) -> None:
    """Rewrite latest-run sort keys so the latest-run join is applied."""
    if not order_by.value:
        return
    normalized = []
    for value in order_by.value:
        descending = value.startswith("-")
        key = value.lstrip("-")
        key = _DAG_SORT_ALIASES.get(key, key)
        normalized.append(f"-{key}" if descending else key)
    if normalized != order_by.value:
        order_by.set_value(normalized)


@dags_router.get("", dependencies=[Depends(requires_access_dag(method="GET"))])
